import sys,numpy as np
from scipy.optimize import least_squares
sys.path.insert(0,'/opt/tools'); import rcb_panda as rp
s=rp.Session(); m,d=s.model,s.data; mj=s.mj; sid=m.site('gripper').id

def logR(R):
 c=np.clip((np.trace(R)-1)/2,-1,1); th=np.arccos(c)
 if th<1e-7:return np.zeros(3)
 if abs(np.sin(th))<1e-6: return np.zeros(3)
 return th/(2*np.sin(th))*np.array([R[2,1]-R[1,2],R[0,2]-R[2,0],R[1,0]-R[0,1]])

def solve(pos,R,q0):
 def fun(q):
  d.qpos[:7]=q; mj.mj_forward(m,d); p=d.site_xpos[sid].copy(); C=d.site_xmat[sid].reshape(3,3).copy(); return np.r_[p-pos, .15*logR(R@C.T)]
 res=least_squares(fun,q0,bounds=(s.lower[:7]+1e-7,s.upper[:7]-1e-7),max_nfev=120,ftol=1e-8,xtol=1e-8,gtol=1e-8)
 return res.x,np.linalg.norm(fun(res.x)),res.nfev
R=np.column_stack(([0,1,0],[0,0,1],[1,0,0]))
angles=np.deg2rad(np.arange(-45,46,15))
for a in angles:
 # rotate local y about local z (world x) with initial y=z, x=y and z=x
 # resulting local y = [0,-sin? ,cos?] world; use axis-angle pre/post accordingly, local roll
 ca,sa=np.cos(a),np.sin(a)
 y=np.array([0,-sa,ca]); x=np.cross(y,[1,0,0]); Rout=np.column_stack((x,y,[1,0,0]))
 sols=[]
 for k in range(20):
  q0=s.data.qpos[:7].copy() if k==0 else np.random.uniform(s.lower[:7]+0.01,s.upper[:7]-0.01)
  q,e,n=solve(np.array([.1966,0,.5]),Rout,q0)
  if e<0.002 and all(np.linalg.norm(q-qq)>0.2 for qq in sols): sols.append(q)
 print('angle',np.rad2deg(a),'solutions',len(sols),[(round(float(np.linalg.norm(q)),2),np.round(q,2).tolist(), 'marg',round(float(min(np.min(q-s.lower[:7]),np.min(s.upper[:7]-q))),2)) for q in sols])
